function generateMap(canvasId) {
  const canvas = document.getElementById(canvasId);
  const ctx = canvas.getContext("2d");
  const width = 500;
  const height = 500;
  const map = Array.from({ length: height }, () =>
    Array(width).fill(0)
  );
  const prio = [];

  function floodFill(x, y) {
    if (
      x < 0 ||
      x >= width ||
      y < 0 ||
      y >= height ||
      map[y][x] !== 0
    )
      return;
    map[y][x] = -1;
    floodFill(x + 1, y);
    floodFill(x - 1, y);
    floodFill(x, y + 1);
    floodFill(x, y - 1);
  }

  function makeRoom(x, y, width, height) {
    for (let i = 0; i < width; i++) {
      for (let j = 0; j < height; j++) {
        map[y][x + i] = 0;
        map[y + j][x] = 0;
      }
    }
    map[y][x] = -1;
    map[y + height - 1][x] = -1;
    map[y][x + width - 1] = -1;
    map[y + height - 1][x + width - 1] = -1;
  }

  function makeCorridor(x1, y1, x2, y2) {
    map[y1][x1] = -1;
    map[y2][x1] = -1;
    map[y1][x2] = -1;
    map[y2][x2] = -1;
    floodFill(x1, y1);
    floodFill(x2, y1);
    floodFill(x1, y2);
    floodFill(x2, y2);
  }

  function makeSpawn(x, y) {
    map[y][x] = 2;
  }

  function makeWeapon(x, y) {
    map[y][x] = 3;
  }

  let startX = Math.floor(Math.random() * 20) * 25;
  let startY = Math.floor(Math.random() * 20) * 25;
  makeRoom(startX, startY, 50, 50);
  let spawns = [[startX + 25, startY + 25]];
  for (let i = 0; i < 10; i++) {
    let x = Math.floor(Math.random() * 20) * 25;
    let y = Math.floor(Math.random() * 20) * 25;
    if (map[y + 25][x + 25] === 0) {
      makeRoom(x, y, 50, 50);
      spawns.push([x + 25, y + 25]);
      for (let j = 0; j < i; j++) {
        makeCorridor(
          x + Math.floor(Math.random() * 25),
          y + Math.floor(Math.random() * 25),
          spawns[j][0],
          spawns[j][1]
        );
      }
    }
    makeSpawn(Math.floor(Math.random() * 25) * 25, Math.floor(Math.random() * 25) * 25);
    makeWeapon(Math.floor(Math.random() * 25) * 25, Math.floor(Math.random() * 25) * 25);
  }
  for (let x = 0; x < width; x++) {
    for (let y = 0; y < height; y++) {
      if (map[y][x] === 0) map[y][x] = 1;
      if (map[y][x] === 1) {
        ctx.fillStyle = "gray";
        ctx.fillRect(x, y, 1, 1);
      }
      if (map[y][x] === -1) {
        ctx.fillStyle = "black";
        ctx.fillRect(x, y, 1, 1);
      }
      if (map[y][x] === 2) {
        ctx.fillStyle = "green";
        ctx.fillRect(x, y, 1, 1);
      }
      if (map[y][x] === 3) {
        ctx.fillStyle = "red";
        ctx.fillRect(x, y, 1, 1);
      }
    }
  }
  document.getElementById("legend").innerText =
    "Floor: Gray\nWall: Black\nGren: Green\nWpn: Red";
  document.getElementById("generate").onclick = () => {
    generateMap(canvasId);
  };
}

generateMap("fps-map");
